use serde::{Deserialize,Serialize};
use std::path::PathBuf;
use std::process::Command;
#[derive(Debug,Serialize)] #[serde(rename_all="camelCase")] struct EngineStatus{available:bool,version:Option<String>,detail:String}
#[derive(Debug,Deserialize)] #[serde(rename_all="camelCase")] struct TransferRequest{archive:String,host:String,port:u16,remote_path:String,username:Option<String>,password:Option<String>}
fn engine_path()->PathBuf{std::env::current_exe().ok().and_then(|p|p.parent().map(|d|d.join("zsftp.exe"))).unwrap_or_else(||PathBuf::from("zsftp.exe"))}
#[tauri::command] fn zsftp_engine_status()->EngineStatus{let path=engine_path();if !path.exists(){return EngineStatus{available:false,version:None,detail:"ZSFTP is not bundled yet. The ZeroSpace Transfer adapter is ready for the existing engine.".into()}}match Command::new(&path).arg("--version").output(){Ok(o)=>{let v=String::from_utf8_lossy(&o.stdout).trim().to_string();EngineStatus{available:o.status.success(),version:if v.is_empty(){None}else{Some(v)},detail:"ZSFTP engine detected.".into()}},Err(e)=>EngineStatus{available:false,version:None,detail:format!("Could not start ZSFTP: {e}")}}}
#[tauri::command] fn start_zsftp_transfer(request:TransferRequest)->Result<String,String>{if request.archive.trim().is_empty()||request.host.trim().is_empty(){return Err("Archive and PS5 IP are required.".into())}let engine=engine_path();if !engine.exists(){return Err("ZSFTP engine is not bundled with this development build yet.".into())}let mut cmd=Command::new(engine);cmd.arg("--file").arg(&request.archive).arg("--host").arg(&request.host).arg("--port").arg(request.port.to_string()).arg("--directory").arg(&request.remote_path);if let Some(v)=request.username.filter(|v|!v.is_empty()){cmd.arg("--user").arg(v);}if let Some(v)=request.password.filter(|v|!v.is_empty()){cmd.arg("--password").arg(v);}cmd.spawn().map(|_|"Transfer started with ZSFTP.".to_string()).map_err(|e|format!("Failed to start ZSFTP: {e}"))}
#[cfg_attr(mobile,tauri::mobile_entry_point)] pub fn run(){tauri::Builder::default().invoke_handler(tauri::generate_handler![zsftp_engine_status,start_zsftp_transfer]).run(tauri::generate_context!()).expect("error while running ZeroSpace");}